<div class="page-head"><div><a href="/app/magazzino" class="text-decoration-none">← Torna al magazzino</a><p class="text-uppercase small fw-semibold text-success mt-3 mb-1"><?= e($prodotto['categoria']) ?><?= $prodotto['codice']?' · '.e($prodotto['codice']):'' ?></p><h1 class="h2 mb-1"><?= e($prodotto['nome']) ?></h1><p class="text-secondary mb-0">Giacenza: <strong><?= e($prodotto['giacenza'].' '.$prodotto['unita_misura']) ?></strong> · Scorta minima: <?= e($prodotto['scorta_minima'].' '.$prodotto['unita_misura']) ?></p></div><?php if($auth->can('magazzino','modifica')): ?><a class="btn btn-outline-primary" href="/app/magazzino/<?= (int)$prodotto['id'] ?>/modifica">Modifica prodotto</a><?php endif ?></div>
<div class="row g-4"><?php if($auth->can('magazzino','modifica')): ?><div class="col-xl-5"><section class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Registra un movimento</h2><p class="small text-secondary">Ogni carico o scarico aggiorna la giacenza e lascia una voce nello storico.</p><form method="post" action="/app/magazzino/<?= (int)$prodotto['id'] ?>/movimenti" class="row g-3"><?= $csrf->field() ?><div class="col-12"><label class="form-label">Operazione<select class="form-select" name="tipo" data-stock-type><option value="carico">Carico · aumenta la scorta</option><option value="scarico">Scarico · diminuisce la scorta</option><option value="rettifica">Rettifica · imposta la giacenza attuale</option></select></label></div><div class="col-12"><label class="form-label" data-stock-quantity-label>Quantità<input class="form-control" type="number" min="0" step="0.001" name="quantita" required><span class="help-text">Unità: <?= e($prodotto['unita_misura']) ?>. Disponibili: <?= e($prodotto['giacenza']) ?>.</span></label></div><div class="col-md-6"><label class="form-label">Lotto <?= $prodotto['tracciamento_lotto']?'*':'(facoltativo)' ?><input class="form-control" name="lotto" <?= $prodotto['tracciamento_lotto']?'required':'' ?>></label></div><div class="col-md-6"><label class="form-label">Scadenza lotto<input class="form-control" type="date" name="scadenza"></label></div><div class="col-12"><label class="form-label">Causale *<input class="form-control" name="causale" required placeholder="Es. acquisto, uso interno, inventario"></label></div><div class="col-12"><button class="btn btn-primary">Registra movimento</button></div></form></div></section></div><?php endif ?><div class="col-xl-7"><section class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Lotti e scadenze</h2><?php if(!$lotti): ?><p class="text-secondary mb-0">Nessun lotto registrato.</p><?php else: ?><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Lotto</th><th>Scadenza</th><th>Quantità</th></tr></thead><tbody><?php foreach($lotti as $l): ?><tr><td><?= e($l['lotto']) ?></td><td><?= e($l['scadenza']?date('d/m/Y',strtotime($l['scadenza'])):'—') ?></td><td><?= e($l['quantita'].' '.$prodotto['unita_misura']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div></section></div></div>
<section class="mt-4"><h2 class="h4">Storico movimenti</h2><?php if(!$movimenti): ?><div class="card border-0 shadow-sm"><div class="empty-state">Nessun movimento: registra il primo carico per valorizzare le scorte.</div></div><?php else: ?><div class="table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Data</th><th>Tipo</th><th>Quantità</th><th>Lotto</th><th>Causale</th><th>Registrato da</th></tr></thead><tbody><?php foreach($movimenti as $m): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($m['creato_il']))) ?></td><td><?= e(ucfirst(str_replace('_',' ',$m['tipo']))) ?></td><td class="<?= (float)$m['quantita']<0?'text-danger':'text-success' ?>"><?= (float)$m['quantita']>0?'+':'' ?><?= e($m['quantita'].' '.$prodotto['unita_misura']) ?></td><td><?= e($m['lotto']?:'—') ?></td><td><?= e($m['causale']) ?></td><td><?= e($m['utente']?:'—') ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
